/** utils/webhook-manager.js
 * Webhook Manager
 * Handles Africa's Talking callbacks and routes to appropriate nodes
 */

const crypto = require('crypto');

class WebhookManager {
  constructor(redisClient) {
    this.redis = redisClient;
    this.nodeRegistry = new Map(); // Maps sessionId to waiting nodes
  }

  /**
   * Register a waiting node for a session
   * @param {string} sessionId - Session identifier
   * @param {Object} nodeInfo - Node info {nodeId, flowId, callback}
   */
  registerWaitingNode(sessionId, nodeInfo) {
    this.nodeRegistry.set(sessionId, nodeInfo);
  }

  /**
   * Unregister waiting node
   */
  unregisterWaitingNode(sessionId) {
    this.nodeRegistry.delete(sessionId);
  }

  /**
   * Get registered node for session
   */
  getWaitingNode(sessionId) {
    return this.nodeRegistry.get(sessionId);
  }

  /**
   * Parse Africa's Talking callback payload
   * Handles SMS replies and voice input
   */
  parseAfricasTalkingPayload(payload) {
    console.log('Parsing Africa\'s Talking payload: ', JSON.stringify(payload));
    try {
      // SMS incoming message
      if (payload.text && payload.from) {
        return {
          type: 'sms',
          sessionId: payload.sessionId || payload.linkId || this.extractSessionFromText(payload),
          phoneNumber: this.formatPhoneNumber(payload.from),
          content: payload.text,
          messageId: payload.id,
          timestamp: new Date().toISOString(),
          rawPayload: payload
        };
      }

      // Voice/IVR callback
      if (payload.sessionId && (payload.dtmfInput || payload.durationInSeconds)) {
        return {
          type: 'dtmf',
          sessionId: payload.sessionId,
          phoneNumber: this.formatPhoneNumber(payload.callerNumber),
          content: payload.dtmfInput || '',
          duration: payload.durationInSeconds,
          callSid: payload.callSid,
          timestamp: new Date().toISOString(),
          rawPayload: payload
        };
      }

      // Voice message transcription
      if (payload.sessionId && payload.text && payload.callerNumber) {
        return {
          type: 'voice',
          sessionId: payload.sessionId,
          phoneNumber: this.formatPhoneNumber(payload.callerNumber),
          content: payload.text,
          confidence: payload.confidence,
          timestamp: new Date().toISOString(),
          rawPayload: payload
        };
      }

      return null;
    } catch (error) {
      console.error('Error parsing Africa\'s Talking payload:', error);
      return null;
    }
  }

  /**
   * Extract session ID from SMS text (if embedded)
   * Format: [SESSION:xyz] message content
   */
  extractSessionFromText(payload) {
    const match = payload.text?.match(/\[SESSION:([^\]]+)\]/);
    return match ? match[1] : null;
  }

  /**
   * Format phone number to E.164
   */
  formatPhoneNumber(phoneNumber) {
    if (!phoneNumber) return null;
    
    let cleaned = phoneNumber.replace(/\D/g, '');
    
    if (!phoneNumber.startsWith('+')) {
      if (cleaned.length === 9) {
        cleaned = '250' + cleaned;
      } else if (cleaned.length === 10 && cleaned.startsWith('0')) {
        cleaned = '250' + cleaned.substring(1);
      }
    }

    return '+' + cleaned;
  }

  /**
   * Verify Africa's Talking signature
   * @param {Object} headers - Request headers
   * @param {string} body - Raw request body
   * @param {string} apiKey - Africa's Talking API key
   */
  verifySignature(headers, body, apiKey) {
    if (!apiKey) {
      console.warn('No API key provided for signature verification');
      return true; // Skip if not configured
    }

    try {
      const signature = headers['x-africastalking-signature'];
      if (!signature) {
        return false;
      }

      const hash = crypto
        .createHmac('sha256', apiKey)
        .update(body)
        .digest('base64');

      return crypto.timingSafeEqual(
        Buffer.from(signature),
        Buffer.from(hash)
      );
    } catch (error) {
      console.error('Signature verification error:', error);
      return false;
    }
  }

  /**
   * Build webhook URL
   * @param {string} baseUrl - Base URL from .env
   * @param {string} path - Path from configuration
   */
  buildWebhookUrl(baseUrl, path) {
    if (!baseUrl) {
      throw new Error('Webhook base URL not configured in .env');
    }

    const cleanBase = baseUrl.replace(/\/$/, '');
    const cleanPath = path.startsWith('/') ? path : '/' + path;

    return cleanBase + cleanPath;
  }
}

module.exports = WebhookManager;